-- Release 2: user lifecycle (edit / archive / restore), session
-- revocation, and ten age-banded EcoGame games.
--
-- Strictly additive: new nullable/defaulted columns, one index, one
-- redefined login function (same signature, same grants), and new
-- `games` rows inserted with `on conflict (key) do nothing`. No row is
-- deleted or rewritten; 0014/0015 are untouched.

-- ── Users ──────────────────────────────────────────────────────────
-- `updated_at` was already written by admin.ts → resolveChildGroup, but
-- the column never existed on `users` (only on `groups`), so resolving
-- a "needs review" child failed with "column updated_at does not
-- exist". Adding it fixes that path without touching the query.
alter table users add column if not exists updated_at timestamptz not null default now();

-- Archive instead of delete: an archived user can't sign in and drops
-- out of active lists, but every row that references them (XP, games,
-- research, photos, audit history) stays exactly as it was.
alter table users add column if not exists archived_at timestamptz;
alter table users add column if not exists archived_by uuid references users(id) on delete set null;

-- Server-side session revocation for the otherwise stateless JWT: a
-- session issued at or before this instant is refused (password reset,
-- archive). Checked on every request by src/lib/auth/dal.ts.
alter table users add column if not exists sessions_revoked_at timestamptz;

create index if not exists idx_users_school_role_active on users(school_id, role) where archived_at is null;

-- Archived accounts can't sign in. Same signature and return shape as
-- 0004, so `create or replace` keeps the owner and the app_user grant.
create or replace function auth_lookup_credentials(p_identifier text)
returns table (
  id uuid,
  school_id uuid,
  role text,
  password_hash text,
  pin_hash text,
  display_name text,
  avatar_url text,
  locale text,
  group_id uuid
)
language sql
security definer
set search_path = public
as $$
  select u.id, u.school_id, u.role, u.password_hash, u.pin_hash,
         u.display_name, u.avatar_url, u.locale, u.group_id
  from users u
  where (u.email = p_identifier or u.login_code = p_identifier)
    and u.archived_at is null
  limit 1;
$$;

